insert into public.letters (letter_id, lao, unicode, kind, name_lao, name_gloss_en, ipa_initial, ipa_final, consonant_class, romanization_bgn, respelling, pron_tip, coverage_required, intro_word_id, source, confidence, notes) values
  ('C01', 'ກ', 'U+0E81', 'consonant', 'ໄກ່', 'chicken', 'k', 'k̚', 'mid', 'k', 'g (final k)', 'Unaspirated k with no puff of air, so English ears often hear it as g (as in ''gas''). As a final it is unreleased.', 'yes', 'W000018', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', null),
  ('C02', 'ຂ', 'U+0E82', 'consonant', 'ໄຂ່', 'egg', 'kʰ', null, 'high', 'kh', 'k', 'Aspirated k as in ''kite''. Same sound as ຄ; the class letter only changes the tone.', 'yes', 'W000006', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', 'WP also lists /x/ as an initial variant'),
  ('C03', 'ຄ', 'U+0E84', 'consonant', 'ຄວາຍ', 'water buffalo', 'kʰ', null, 'low', 'kh', 'k', 'Aspirated k as in ''kite''. Same sound as ຂ.', 'yes', 'W000040', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', 'WP also lists /x/ as an initial variant'),
  ('C04', 'ງ', 'U+0E87', 'consonant', 'ງົວ', 'ox', 'ŋ', 'ŋ', 'low', 'ng', 'ng', 'The ''ng'' of ''singer'', but it can start a word.', 'yes', 'W000012', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', 'WP gives ງົວ ox or ງູ snake as the name word'),
  ('C05', 'ຈ', 'U+0E88', 'consonant', 'ຈອກ', 'glass', 'tɕ', null, 'mid', 'ch', 'j', 'Between English j and ch: like the j in ''jaw'' but voiceless.', 'yes', 'W000005', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', 'WP also gives ຈົວ novice as the name word'),
  ('C06', 'ສ', 'U+0EAA', 'consonant', 'ເສືອ', 'tiger', 's', null, 'high', 's', 's', 's as in ''saw''. Same sound as ຊ.', 'yes', 'W000001', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', 'Out of alphabetical order in the Unicode block (Thai position)'),
  ('C07', 'ຊ', 'U+0E8A', 'consonant', 'ຊ້າງ', 'elephant', 's', null, 'low', 'x', 's', 's as in ''saw''. Same sound as ສ.', 'yes', 'W000041', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', 'BGN/PCGN romanizes it x'),
  ('C08', 'ຍ', 'U+0E8D', 'consonant', 'ຍຸງ', 'mosquito', 'ɲ', 'j', 'low', 'gn/ny', 'ny (final i/y)', 'At the start it is a nasal ''ny'' (Spanish ñ, Russian ''nyet''). At the end of a syllable it is a y glide.', 'yes', 'W000001', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', null),
  ('C09', 'ດ', 'U+0E94', 'consonant', 'ເດັກ', 'child', 'd', 't̚', 'mid', 'd', 'd (final t)', 'd as in ''deck''. As a final it is an unreleased t.', 'yes', 'W000001', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', null),
  ('C10', 'ຕ', 'U+0E95', 'consonant', 'ຕາ', 'eye', 't', null, 'mid', 't', 'dt', 'Unaspirated t, like the t in ''stay'' (no puff of air).', 'yes', 'W000067', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', null),
  ('C11', 'ຖ', 'U+0E96', 'consonant', 'ຖົງ', 'bag', 'tʰ', null, 'high', 'th', 't', 'Aspirated t as in ''top'' (not the ''th'' of ''think''). Same sound as ທ.', 'yes', 'W000088', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', null),
  ('C12', 'ທ', 'U+0E97', 'consonant', 'ທຸງ', 'flag', 'tʰ', null, 'low', 'th', 't', 'Aspirated t as in ''top'' (not the ''th'' of ''think''). Same sound as ຖ.', 'yes', 'W000010', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', null),
  ('C13', 'ນ', 'U+0E99', 'consonant', 'ນົກ', 'bird', 'n', 'n', 'low', 'n', 'n', 'n as in ''no''.', 'yes', 'W000004', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', null),
  ('C14', 'ບ', 'U+0E9A', 'consonant', 'ແບ້', 'goat', 'b', 'p̚', 'mid', 'b', 'b (final p)', 'b as in ''boy''. As a final it is an unreleased p.', 'yes', 'W000001', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', null),
  ('C15', 'ປ', 'U+0E9B', 'consonant', 'ປາ', 'fish', 'p', null, 'mid', 'p', 'bp', 'Unaspirated p, like the p in ''spy'' (no puff of air).', 'yes', 'W000024', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', null),
  ('C16', 'ຜ', 'U+0E9C', 'consonant', 'ເຜິ້ງ', 'bee', 'pʰ', null, 'high', 'ph', 'p', 'Aspirated p as in ''pie'' (not an f). Same sound as ພ.', 'yes', 'W000046', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', null),
  ('C17', 'ຝ', 'U+0E9D', 'consonant', 'ຝົນ', 'rain', 'f', null, 'high', 'f', 'f', 'f as in ''finch''. Same sound as ຟ.', 'yes', 'W000120', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', 'Unicode name FO TAM is swapped relative to the Lao name (WP; compart confirms)'),
  ('C18', 'ພ', 'U+0E9E', 'consonant', 'ພູ', 'mountain', 'pʰ', null, 'low', 'ph', 'p', 'Aspirated p as in ''pie'' (not an f). Same sound as ຜ.', 'yes', 'W000043', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', null),
  ('C19', 'ຟ', 'U+0E9F', 'consonant', 'ໄຟ', 'fire', 'f', null, 'low', 'f', 'f', 'f as in ''finch''. Same sound as ຝ.', 'yes', 'W000080', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', 'Unicode name FO SUNG is swapped relative to the Lao name (WP; compart confirms)'),
  ('C20', 'ມ', 'U+0EA1', 'consonant', 'ແມວ', 'cat', 'm', 'm', 'low', 'm', 'm', 'm as in ''man''.', 'yes', 'W000004', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', null),
  ('C21', 'ຢ', 'U+0EA2', 'consonant', 'ຢາ', 'medicine', 'j', null, 'mid', 'y', 'y', 'y as in ''young''. Never used as a final.', 'yes', 'W000014', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', null),
  ('C22', 'ຣ', 'U+0EA3', 'consonant', null, null, 'r', 'n', 'low', 'r', 'r', 'Usually pronounced like ລ (l).', 'reading-only', null, 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', 'Name word UNCERTAIN (fetches gave ຣົຖ or ລົດ). Used mainly in foreign names and loans. Unicode name LO LING is swapped relative to the Lao name'),
  ('C23', 'ລ', 'U+0EA5', 'consonant', 'ລີງ', 'monkey', 'l', null, 'low', 'l', 'l', 'l as in ''law''.', 'yes', 'W000020', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', 'Unicode name LO LOOT is swapped relative to the Lao name'),
  ('C24', 'ວ', 'U+0EA7', 'consonant', 'ວີ', 'fan', 'w', 'w', 'low', 'v/w', 'w (final o/w)', 'At the start, between English w and v. At the end of a syllable it is a w glide (as in ''now'').', 'yes', 'W000020', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', 'WP: [ʋ] or [w] depending on dialect'),
  ('C25', 'ຫ', 'U+0EAB', 'consonant', 'ຫ່ານ', 'goose', 'h', null, 'high', 'h', 'h', 'h as in ''hang''. Written silent before ງ ຍ ນ ມ ລ ວ, it makes them high class.', 'yes', 'W000012', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', null),
  ('C26', 'ອ', 'U+0EAD', 'consonant', 'ໂອ', 'bowl', 'ʔ', null, 'mid', null, null, 'Silent carrier for a vowel at the start of a syllable. Strictly a glottal catch, like the break in ''uh-oh''.', 'yes', 'W000028', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', 'WP also gives ອື່ງ frog as the name word. Also part of the vowel forms ◌ອ◌ ◌ັອ◌ ເ◌ືອ ເ◌ຶອ'),
  ('C27', 'ຮ', 'U+0EAE', 'consonant', 'ເຮືອ', 'boat', 'h', null, 'low', 'h', 'h', 'h as in ''hang''. Same sound as ຫ.', 'yes', 'W000029', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', 'WP also gives ເຮືອນ house as the name word'),
  ('C28', 'ຫງ', 'U+0EAB U+0E87', 'consonant-cluster', 'ເຫງົາ', 'lonely', 'ŋ', null, 'high', 'ng', 'ng', 'Same sound as ງ; high class (silent ຫ).', 'yes', 'W000302', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', 'Example word from WP. SEAsite gives ເຫງັນ civet cat'),
  ('C29', 'ຫຍ', 'U+0EAB U+0E8D', 'consonant-cluster', 'ຫຍ້າ', 'grass', 'ɲ', null, 'high', 'ny', 'ny', 'Same sound as initial ຍ; high class (silent ຫ).', 'yes', 'W000026', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', null),
  ('C30', 'ໜ', 'U+0EDC', 'consonant-ligature', 'ໜູ', 'rat', 'n', null, 'high', 'n', 'n', 'Same sound as ນ; high class. Also written ຫນ.', 'yes', 'W000039', 'SRC-WP-SCRIPT;SRC-SEASITE;SRC-COMPART', 'verified', 'Unicode LAO HO NO'),
  ('C31', 'ໝ', 'U+0EDD', 'consonant-ligature', 'ໝາ', 'dog', 'm', null, 'high', 'm', 'm', 'Same sound as ມ; high class. Also written ຫມ.', 'yes', 'W000045', 'SRC-WP-SCRIPT;SRC-SEASITE;SRC-COMPART', 'verified', 'Unicode LAO HO MO'),
  ('C32', 'ຫຼ', 'U+0EAB U+0EBC', 'consonant-ligature', 'ຫຼັງ', 'back', 'l', null, 'high', 'l', 'l', 'Same sound as ລ; high class. Also written ຫລ.', 'yes', 'W000091', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', 'ຫ + subscript ◌ຼ (U+0EBC); no single code point. SEAsite example ຫຼາ spinner'),
  ('C33', 'ຫວ', 'U+0EAB U+0EA7', 'consonant-cluster', 'ແຫວນ', 'ring', 'w', null, 'high', 'w/v', 'w', 'Same sound as initial ວ; high class (silent ຫ).', 'yes', 'W000126', 'SRC-WP-SCRIPT;SRC-SEASITE', 'verified', 'SEAsite example ຫວີ comb. ຫຣ sometimes listed as a 7th; not counted (see notes)'),
  ('T1', '◌່', 'U+0EC8', 'tone-mark', 'ໄມ້ເອກ', 'mai ek', null, null, null, null, null, 'Gives the mid tone for every class.', 'yes', 'W000003', 'SRC-WP-SCRIPT;SRC-SEASITE;SRC-WIKT-GUIDE', 'verified', 'Lao spelling of the name UNVERIFIED'),
  ('T2', '◌້', 'U+0EC9', 'tone-mark', 'ໄມ້ໂທ', 'mai tho', null, null, null, null, null, 'Gives low-falling after high-class letters, high-falling after mid- and low-class letters.', 'yes', 'W000005', 'SRC-WP-SCRIPT;SRC-SEASITE;SRC-WIKT-GUIDE', 'verified', 'Lao spelling of the name UNVERIFIED'),
  ('T3', '◌໊', 'U+0ECA', 'tone-mark', null, 'mai ti', null, null, null, null, null, 'Rare: interjections and onomatopoeia, normally with mid-class letters (Kerr).', 'no', null, 'SRC-WP-SCRIPT;SRC-KERR', 'verified', 'Tone value only from uncited Wiktionary code (high-rising): unverified'),
